import sys

def main():
    line = sys.stdin.readline().strip()
    if not line:
        print(0)
        return

    parts = line.rsplit(' ', 1)
    if len(parts) < 2:
        print(0)
        return

    word = parts[0]
    ch = parts[1]

    if not ch:
        print(0)
        return

    ch = ch[0]

    count = 0
    for c in word:
        if c == ch:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
